@font-face { font-family: 'Outfit'; src: url('./assets/fonts/Outfit-Regular.ttf') format('truetype'); font-weight: 300 400; font-display: swap; }
@font-face { font-family: 'Outfit'; src: url('./assets/fonts/Outfit-SemiBold.ttf') format('truetype'); font-weight: 500 600; font-display: swap; }
@font-face { font-family: 'Outfit'; src: url('./assets/fonts/Outfit-Bold.ttf') format('truetype'); font-weight: 700; font-display: swap; }
