.hero-palm.p1 { left: 76%; bottom: 19%; height: 42%; opacity: .86; }
.hero-palm.p2 { left: 87%; bottom: 15%; height: 31%; transform: rotate(5deg) scale(.8); opacity: .65; }
.hero-car { position: absolute; right: 10%; bottom: 9%; width: 30%; height: 13%; background: linear-gradient(175deg, #ff795c, #b53b34 55%, #6d1f24); border-radius: 55% 20% 12% 10%; box-shadow: 0 16px 20px rgba(0,0,0,.6); transform: skewX(-12deg); opacity: .9; }
.hero-car::before { content: ''; position: absolute; left: 20%; top: -44%; width: 46%; height: 52%; background: linear-gradient(150deg, #512b3d, #14242d); border-radius: 40% 45% 0 0; border: 1px solid rgba(255,203,151,.14); }
.hero-car::after { content: ''; position: absolute; left: 10%; bottom: -8%; width: 80%; height: 12%; background: radial-gradient(ellipse, rgba(255,121,92,.26), transparent 65%); }
.hero-grain { position: absolute; inset: 0; opacity: .18; background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 120 120' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='a'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.75' numOctaves='2'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23a)' opacity='.5'/%3E%3C/svg%3E"); mix-blend-mode: overlay; }
.hero-content { position: relative; z-index: 3; padding: clamp(28px, 3.4vw, 48px); display: flex; flex-direction: column; justify-content: center; width: 62%; min-height: clamp(360px, 47vh, 510px); }
.hero-badges { display: flex; gap: 7px; margin-bottom: 22px; }
.badge { display: inline-flex; padding: 5px 8px; border: 1px solid rgba(255,255,255,.25); border-radius: 3px; font-size: 7px; font-weight: 700; letter-spacing: .16em; color: #e9f4f0; background: rgba(5,15,16,.26); backdrop-filter: blur(5px); }
.badge.exclusive { background: var(--coral); border-color: var(--coral); color: #250808; }
.hero-kicker { font-size: 8px; letter-spacing: .34em; color: var(--gold); margin-bottom: 2px; }
.hero-content h2 { font-family: 'Barlow Condensed'; font-weight: 800; font-size: clamp(56px, 7.1vw, 108px); line-height: .82; letter-spacing: -.005em; color: #fffdf4; text-shadow: 0 7px 38px rgba(0,0,0,.3); }
