.chapter-art i { position: absolute; right: 8px; top: 8px; width: 18px; height: 18px; border: 1px solid rgba(255,255,255,.35); border-radius: 50%; }
.continue-info { flex: 1; min-width: 0; }
.continue-bar { height: 2px; background: rgba(255,255,255,.09); }
