.emu-footer { position: absolute; left: 0; right: 0; bottom: 0; height: 48px; display: flex; align-items: center; justify-content: space-between; padding: 0 42px; border-top: 1px solid rgba(255,255,255,.045); color: rgba(145,165,162,.42); font-size: 7.5px; letter-spacing: .12em; }
