.menu-copy h1 { font-family: 'Barlow Condensed'; font-weight: 800; font-size: clamp(78px, 11vw, 164px); line-height: .77; letter-spacing: -.01em; color: #fffaf0; margin-top: 17px; text-shadow: 0 15px 60px rgba(0,0,0,.45); }
.menu-copy h1 em { font-style: normal; color: var(--gold); }
.menu-copy h1 span { font-size: .48em; letter-spacing: .02em; margin-left: 4px; }
.menu-copy h2 { font-family: 'Barlow Condensed'; font-size: clamp(18px, 2.1vw, 29px); font-weight: 700; letter-spacing: .47em; color: var(--gold); margin-top: 7px; }
.menu-tagline { font-size: clamp(12px, 1.06vw, 15px); line-height: 1.55; color: rgba(233,240,235,.62); margin-top: 18px; letter-spacing: .015em; }
.menu-meta { display: flex; gap: 9px; margin-top: 18px; flex-wrap: wrap; }
.menu-meta span { padding: 4px 8px; border: 1px solid rgba(255,255,255,.14); border-radius: 2px; font-size: 6.5px; letter-spacing: .15em; color: rgba(226,235,230,.67); }
.menu-actions { display: flex; flex-direction: column; width: min(460px, 100%); margin-top: clamp(20px, 3.5vh, 38px); }
.menu-item { position: relative; display: flex; align-items: center; gap: 17px; padding: 14px 18px; border-top: 1px solid rgba(255,255,255,.13); text-align: left; color: var(--paper); transition: .22s ease; overflow: hidden; }
.menu-item:last-child { border-bottom: 1px solid rgba(255,255,255,.13); }
.menu-item::before { content: ''; position: absolute; inset: 0; background: linear-gradient(90deg, rgba(246,199,104,.14), transparent 80%); opacity: 0; transition: .25s; }
.menu-item:hover::before, .menu-item.featured::before { opacity: 1; }
.menu-item.featured { border-top-color: var(--line-gold); }
.menu-item:hover { padding-left: 24px; }
.mi-index { font-size: 8px; color: var(--gold); letter-spacing: .1em; width: 18px; position: relative; }
.mi-text { flex: 1; position: relative; }
.mi-text b { display: block; font-family: 'Barlow Condensed'; font-size: clamp(21px, 2vw, 27px); font-weight: 700; letter-spacing: .03em; line-height: 1.05; }
.mi-text small { display: block; font-size: 8px; color: rgba(199,214,208,.5); margin-top: 3px; letter-spacing: .04em; }
.mi-arrow { position: relative; font-size: 18px; color: var(--gold); opacity: .1; transition: .25s; }
.menu-item:hover .mi-arrow, .menu-item.featured .mi-arrow { opacity: 1; transform: translateX(3px); }
.menu-side { justify-self: end; width: min(330px, 100%); display: flex; flex-direction: column; gap: 14px; }
.character-showcase { position: relative; border: 1px solid rgba(255,255,255,.13); background: linear-gradient(155deg, rgba(19,45,46,.8), rgba(6,17,19,.86)); border-radius: 12px; padding: 18px; box-shadow: var(--shadow); backdrop-filter: blur(12px); overflow: hidden; }
.character-showcase::before { content: ''; position: absolute; right: -50px; top: -60px; width: 220px; height: 220px; border-radius: 50%; background: radial-gradient(circle, rgba(255,112,88,.2), transparent 65%); }
.char-glow { position: absolute; left: 25%; bottom: -80px; width: 200px; height: 150px; background: radial-gradient(ellipse, rgba(246,199,104,.14), transparent 70%); }
.char-badge { position: relative; font-size: 7px; letter-spacing: .24em; color: var(--gold); margin-bottom: 14px; }
.char-row { display: flex; flex-direction: column; gap: 8px; position: relative; }
.char-card { display: flex; align-items: center; gap: 11px; padding: 10px 11px; border: 1px solid rgba(255,255,255,.1); border-radius: 5px; background: rgba(2,9,10,.4); }
.char-card.luiza { border-left: 2px solid var(--coral); }
.char-card.carlos { border-left: 2px solid var(--teal); }
.char-initials { width: 35px; height: 35px; border-radius: 50%; display: grid; place-items: center; font-family: 'Barlow Condensed'; font-weight: 800; font-size: 20px; background: linear-gradient(135deg, #623a3f, #241a25); color: #ffd4c8; border: 1px solid rgba(255,112,88,.4); }
.char-card.carlos .char-initials { background: linear-gradient(135deg, #244f49, #101e23); color: #bcfff0; border-color: rgba(67,221,190,.4); }
.char-card div { flex: 1; }
.char-card b { display: block; font-family: 'Barlow Condensed'; font-size: 16px; letter-spacing: .09em; }
.char-card small { font-size: 7px; color: var(--muted); letter-spacing: .05em; }
.char-card i { font-style: normal; font-size: 8px; color: rgba(255,255,255,.25); }
.menu-side-card { border: 1px solid rgba(255,255,255,.1); border-radius: 10px; padding: 15px 17px; background: rgba(5,15,17,.64); backdrop-filter: blur(12px); }
.session-row { display: flex; justify-content: space-between; align-items: center; padding: 7px 0; border-bottom: 1px solid rgba(255,255,255,.05); font-size: 8px; color: var(--muted); }
.session-row:last-child { border-bottom: 0; }
.session-row b { font-size: 9px; font-weight: 500; color: #dfe9e5; display: flex; align-items: center; gap: 5px; }
.dot { display: inline-block; width: 5px; height: 5px; border-radius: 50%; background: var(--teal); }
.dot.green { background: var(--teal); box-shadow: 0 0 6px var(--teal); }
.menu-side-note { display: flex; gap: 10px; align-items: flex-start; padding: 0 4px; color: rgba(145,165,162,.4); font-size: 7.5px; line-height: 1.5; }
.menu-side-note span { color: var(--gold); }
.menu-footer { position: absolute; bottom: 0; left: 0; right: 0; height: 50px; padding: 0 5vw; display: flex; justify-content: space-between; align-items: center; font-size: 6.5px; letter-spacing: .14em; color: rgba(197,213,207,.32); border-top: 1px solid rgba(255,255,255,.05); z-index: 3; }

/* ================= LOADING ================= */
.loading-screen { z-index: 48; background: #061214; overflow: hidden; }
.loading-screen.visible { display: block; }
.loading-art { position: absolute; inset: 0; background: linear-gradient(180deg, #1d3b56, #c36e64 47%, #f5ae74 58%, #1e4f55 59%, #082129); }
.load-sun { position: absolute; width: 27vw; height: 27vw; border-radius: 50%; left: 56%; top: 24%; background: radial-gradient(circle, #fff4cf 0 8%, #ffc476 20%, rgba(255,133,92,.5) 44%, transparent 68%); filter: blur(5px); }
.load-city { position: absolute; left: 0; right: 0; bottom: 29%; height: 25%; background: #0a1c23; clip-path: polygon(0 100%,0 70%,4% 70%,4% 52%,7% 52%,7% 61%,12% 61%,12% 38%,16% 38%,16% 58%,21% 58%,21% 48%,25% 48%,25% 68%,30% 68%,30% 26%,36% 26%,36% 58%,41% 58%,41% 44%,45% 44%,45% 61%,51% 61%,51% 33%,57% 33%,57% 64%,62% 64%,62% 49%,67% 49%,67% 57%,72% 57%,72% 36%,78% 36%,78% 62%,84% 62%,84% 47%,90% 47%,90% 65%,100% 65%,100% 100%); }
.load-sea { position: absolute; left: 0; right: 0; bottom: 0; height: 30%; background: linear-gradient(180deg, #0e3d4a, #051821); }
.load-sea::after { content: ''; position: absolute; inset: 0; background: repeating-linear-gradient(177deg, transparent 0 12px, rgba(255,173,123,.17) 13px, transparent 14px 25px); opacity: .65; }
.loading-screen::after { content: ''; position: absolute; inset: 0; background: linear-gradient(90deg, rgba(3,9,10,.92), rgba(3,9,10,.3) 55%, transparent), linear-gradient(0deg, rgba(3,9,10,.97), transparent 70%); }
.loading-content { position: absolute; z-index: 2; left: 7vw; bottom: 14vh; width: min(640px, 80vw); }
.loading-content h1 { font-family: 'Barlow Condensed'; font-size: clamp(58px, 8.4vw, 120px); font-weight: 800; line-height: .85; letter-spacing: .01em; margin-top: 12px; }
.loading-content h2 { font-size: 11px; letter-spacing: .28em; color: var(--gold); font-weight: 400; margin-top: 15px; }
.loading-track { height: 2px; width: 100%; background: rgba(255,255,255,.12); margin-top: 30px; overflow: hidden; }
.loading-track i { display: block; height: 100%; width: 0; background: var(--gold); transition: width .4s; box-shadow: 0 0 15px rgba(246,199,104,.5); }
.loading-hint { font-size: 8px; color: rgba(211,226,220,.5); margin-top: 11px; letter-spacing: .06em; }

/* ================= HUD ================= */
.hud { position: absolute; inset: 0; z-index: 10; pointer-events: none; opacity: var(--hud-opacity); font-size: calc(12px * var(--hud-scale)); }
.hud > * { pointer-events: none; }
.hud button { pointer-events: auto; }
#top-left { position: absolute; top: calc(24px + var(--safe-top)); left: calc(26px + var(--safe-left)); display: flex; flex-direction: column; gap: 9px; }
.minimap-shell { position: relative; width: calc(196px * var(--hud-scale)); height: calc(196px * var(--hud-scale)); border-radius: 50%; background: #0a1819; border: 2px solid rgba(250,250,244,.8); box-shadow: 0 6px 35px rgba(0,0,0,.65), 0 0 0 5px rgba(3,8,9,.35); overflow: hidden; pointer-events: auto; }
.minimap-shell::before { content: ''; position: absolute; inset: 0; border-radius: 50%; box-shadow: inset 0 0 28px rgba(0,0,0,.55); z-index: 2; pointer-events: none; }
#minimap { width: 100%; height: 100%; display: block; }
.minimap-ring { position: absolute; inset: 7px; border: 1px solid rgba(255,255,255,.24); border-radius: 50%; z-index: 3; pointer-events: none; }
.minimap-ring::before, .minimap-ring::after { content: ''; position: absolute; width: 4px; height: 4px; border-radius: 50%; background: rgba(255,255,255,.4); top: 50%; left: -3px; }
.minimap-ring::after { left: auto; right: -3px; }
.minimap-header { position: absolute; left: 18px; right: 18px; top: 17px; display: flex; justify-content: space-between; font-size: calc(6.5px * var(--hud-scale)); letter-spacing: .16em; color: rgba(255,255,255,.84); z-index: 4; text-shadow: 0 1px 4px #000; }
.minimap-expand { position: absolute; right: 13px; bottom: 13px; z-index: 6; width: 27px; height: 27px; border-radius: 50%; display: grid; place-items: center; background: rgba(4,12,13,.84); border: 1px solid rgba(255,255,255,.3); color: var(--paper); font-size: 12px; }
.minimap-expand:hover { background: var(--gold); color: #1b1408; }
.minimap-compass { position: absolute; top: 5px; left: 50%; transform: translateX(-50%); z-index: 4; font-size: calc(7px * var(--hud-scale)); font-weight: 700; color: var(--gold); text-shadow: 0 1px 4px #000; }
.district-card { display: flex; align-items: center; gap: 8px; padding: 7px 11px; border-left: 2px solid var(--gold); background: linear-gradient(90deg, rgba(3,10,11,.8), rgba(3,10,11,.3)); backdrop-filter: blur(6px); width: max-content; }
.district-line { width: 3px; }
.district-card b { display: block; font-size: calc(10px * var(--hud-scale)); font-weight: 600; letter-spacing: .03em; text-shadow: 0 1px 4px #000; }
.district-card small { display: block; font-size: calc(7px * var(--hud-scale)); color: var(--muted); letter-spacing: .04em; }
.activity-chips { display: flex; gap: 5px; }
.activity-chips span { display: inline-flex; align-items: center; gap: 4px; padding: 4px 7px; background: rgba(4,11,12,.6); border: 1px solid rgba(255,255,255,.1); border-radius: 2px; font-size: calc(6.5px * var(--hud-scale)); letter-spacing: .09em; color: #bccfca; }
.activity-chips span i { width: 4px; height: 4px; background: var(--teal); border-radius: 50%; }

#top-right { position: absolute; top: calc(25px + var(--safe-top)); right: calc(27px + var(--safe-right)); display: flex; flex-direction: column; align-items: flex-end; gap: 8px; }
.wanted-stars { display: flex; gap: 3px; filter: drop-shadow(0 2px 5px rgba(0,0,0,.7)); min-height: 17px; }
.star-icon { font-size: calc(18px * var(--hud-scale)); line-height: 1; color: rgba(255,255,255,.15); transition: .25s; position: relative; }
.star-icon.on { color: var(--gold); text-shadow: 0 0 12px rgba(246,199,104,.55); }
.star-icon.active-six.on { color: #ff5448; text-shadow: 0 0 16px rgba(255,75,66,.8); animation: dangerPulse .8s infinite alternate; }
.wanted-label { display: flex; align-items: center; gap: 6px; font-size: calc(6.5px * var(--hud-scale)); letter-spacing: .2em; color: rgba(255,255,255,.58); margin-top: 1px; }
.wanted-label i { width: 36px; height: 1px; background: rgba(255,255,255,.2); }
.wanted-shell.hot .wanted-label { color: var(--coral); }
.search-progress { width: 132px; height: 2px; background: rgba(255,255,255,.14); opacity: 0; transition: opacity .3s; }
.search-progress.on { opacity: 1; }
.search-progress i { display: block; width: 0; height: 100%; background: var(--blue); }
.clock-weather { display: flex; align-items: center; gap: 9px; text-align: right; }
.clock-time { font-family: 'Barlow Condensed'; font-size: calc(29px * var(--hud-scale)); font-weight: 700; line-height: 1; text-shadow: 0 2px 10px rgba(0,0,0,.6); }
.clock-day { font-size: calc(6.5px * var(--hud-scale)); letter-spacing: .13em; color: var(--muted); }
.weather-icon { width: 20px; height: 20px; position: relative; }
.moon { position: absolute; width: 13px; height: 13px; border-radius: 50%; box-shadow: inset -4px -2px 0 0 #f6d998; transform: rotate(-20deg); }
.money-shell { display: flex; align-items: baseline; gap: 7px; margin-top: 4px; }
.money-shell span { font-size: calc(6px * var(--hud-scale)); color: var(--muted); letter-spacing: .18em; }
.money-shell b { font-family: 'Barlow Condensed'; font-size: calc(21px * var(--hud-scale)); font-weight: 700; color: var(--teal); letter-spacing: .02em; text-shadow: 0 1px 5px #000; }
.money-shell i { font-style: normal; color: var(--teal); font-size: calc(9px * var(--hud-scale)); opacity: 0; }
.fps-badge { font-size: 7px; letter-spacing: .12em; padding: 2px 5px; background: rgba(3,10,11,.5); color: rgba(255,255,255,.4); border: 1px solid rgba(255,255,255,.08); margin-top: 2px; }

.objective-panel { position: absolute; top: calc(25px + var(--safe-top)); left: 50%; transform: translateX(-50%); width: min(350px, 38vw); padding: 12px 16px; background: linear-gradient(180deg, rgba(4,12,13,.84), rgba(4,12,13,.55)); border-top: 1px solid rgba(246,199,104,.45); border-bottom: 1px solid rgba(255,255,255,.08); backdrop-filter: blur(8px); text-align: center; clip-path: polygon(9px 0, 100% 0, 100% calc(100% - 9px), calc(100% - 9px) 100%, 0 100%, 0 9px); }
.objective-kicker { display: flex; align-items: center; justify-content: center; gap: 7px; font-size: calc(6.5px * var(--hud-scale)); letter-spacing: .19em; color: var(--gold); }
.objective-kicker i { width: 14px; height: 1px; background: var(--gold); opacity: .6; }
.objective-panel h3 { font-family: 'Barlow Condensed'; font-size: calc(17px * var(--hud-scale)); font-weight: 700; letter-spacing: .08em; margin-top: 4px; color: var(--paper); }
.objective-panel p { font-size: calc(8px * var(--hud-scale)); line-height: 1.4; color: rgba(220,231,226,.65); margin-top: 2px; }
.objective-dist { display: flex; align-items: center; justify-content: center; gap: 6px; font-size: calc(7px * var(--hud-scale)); margin-top: 7px; color: var(--muted); }
.waypoint-dot { width: 6px; height: 6px; border: 1px solid var(--gold); transform: rotate(45deg); display: inline-block; }
.objective-dist b { color: var(--gold); font-weight: 500; }
#objective-extra { margin-left: 5px; font-size: calc(5.5px * var(--hud-scale)); letter-spacing: .1em; padding: 2px 4px; border: 1px solid rgba(246,199,104,.25); color: var(--gold); }
.objective-progress { height: 2px; background: rgba(255,255,255,.1); margin-top: 8px; display: none; }
.objective-progress.on { display: block; }
.objective-progress i { display: block; height: 100%; width: 0; background: var(--gold); transition: width .1s linear; }

.crosshair { position: absolute; left: 50%; top: 50%; width: 30px; height: 30px; transform: translate(-50%, -50%); opacity: .65; }
.crosshair span { position: absolute; inset: 8px; border: 1px solid rgba(255,255,255,.7); border-radius: 50%; }
.crosshair i, .crosshair b, .crosshair em { position: absolute; background: rgba(255,255,255,.8); }
.crosshair i { width: 1px; height: 6px; left: 50%; top: -2px; }
.crosshair b { width: 1px; height: 6px; left: 50%; bottom: -2px; }
.crosshair em { height: 1px; width: 6px; top: 50%; left: -2px; }
.crosshair::after { content: ''; position: absolute; height: 1px; width: 6px; background: rgba(255,255,255,.8); right: -2px; top: 50%; }
.crosshair.aiming { opacity: 1; transform: translate(-50%,-50%) scale(.68); }
.crosshair.hit span { border-color: var(--coral); }
.hitmarker { position: absolute; left: 50%; top: 50%; transform: translate(-50%,-50%); font-size: 24px; color: #fff; opacity: 0; text-shadow: 0 0 9px rgba(255,70,60,.8); }
.hitmarker.show { animation: hit .28s ease; }
#damage-vignette { position: absolute; inset: 0; box-shadow: inset 0 0 120px 40px rgba(255,31,31,.55); opacity: 0; transition: opacity .25s; }
#damage-vignette.show { opacity: 1; }
#low-health { position: absolute; inset: 0; box-shadow: inset 0 0 100px 20px rgba(150,18,18,.35); opacity: 0; animation: lowHealth 2.4s infinite; pointer-events: none; }
#low-health.on { opacity: 1; }

#bottom-left { position: absolute; left: calc(27px + var(--safe-left)); bottom: calc(28px + var(--safe-bottom)); display: flex; flex-direction: column; gap: 9px; }
.player-card { display: flex; align-items: center; gap: 10px; }
.player-avatar { width: calc(41px * var(--hud-scale)); height: calc(41px * var(--hud-scale)); border-radius: 50%; display: grid; place-items: center; font-family: 'Barlow Condensed'; font-size: calc(19px * var(--hud-scale)); font-weight: 800; color: #ffd0c2; background: linear-gradient(135deg, #6b353a, #281a22); border: 1px solid rgba(255,112,88,.7); box-shadow: 0 0 0 3px rgba(3,9,10,.4); }
.player-avatar.carlos { color: #bafff0; border-color: rgba(67,221,190,.7); background: linear-gradient(135deg, #1d514a, #0d2024); }
.player-info { width: calc(180px * var(--hud-scale)); }
.player-name { display: flex; align-items: baseline; justify-content: space-between; margin-bottom: 5px; }
.player-name b { font-family: 'Barlow Condensed'; font-size: calc(14px * var(--hud-scale)); letter-spacing: .1em; text-shadow: 0 1px 4px #000; }
.player-name span { font-size: calc(5.5px * var(--hud-scale)); letter-spacing: .12em; color: var(--gold); }
.health-bar { height: calc(7px * var(--hud-scale)); background: rgba(0,0,0,.55); border: 1px solid rgba(255,255,255,.18); position: relative; }
.health-bar i { display: block; height: 100%; width: 100%; background: linear-gradient(90deg, #8de2ad, #43c97d); box-shadow: 0 0 7px rgba(67,201,125,.35); transition: width .25s; }
.health-bar.low i { background: linear-gradient(90deg, #ff7359, #d82f2f); }
.health-bar span { position: absolute; right: 4px; top: -14px; font-size: calc(6px * var(--hud-scale)); color: rgba(255,255,255,.7); }
.armor-bar { height: calc(3px * var(--hud-scale)); background: rgba(0,0,0,.45); margin-top: 3px; width: 70%; }
.armor-bar i { display: block; height: 100%; background: var(--blue); width: 0; }
.stamina-row { display: flex; align-items: center; gap: 7px; }
.stamina-row span { font-size: calc(5.5px * var(--hud-scale)); letter-spacing: .14em; color: var(--muted-2); }
.stamina-bar { width: calc(130px * var(--hud-scale)); height: 2px; background: rgba(255,255,255,.1); }
.stamina-bar i { display: block; height: 100%; width: 100%; background: rgba(246,199,104,.75); transition: width .2s; }
.radio-row { display: flex; align-items: center; gap: 7px; margin-top: 7px; width: max-content; }
.radio-btn { width: 24px; height: 24px; border-radius: 50%; border: 1px solid rgba(255,255,255,.22); background: rgba(4,11,12,.65); font-size: 11px; color: var(--gold); padding: 0; }
.radio-next { color: rgba(255,255,255,.4); font-size: 17px; padding: 0 4px; }
.radio-row div { min-width: 95px; }
.radio-row span { display: block; font-size: calc(5.5px * var(--hud-scale)); letter-spacing: .15em; color: var(--muted-2); }
.radio-row b { display: block; font-size: calc(7px * var(--hud-scale)); letter-spacing: .1em; color: #cddcd7; font-weight: 500; }

#bottom-right { position: absolute; right: calc(27px + var(--safe-right)); bottom: calc(28px + var(--safe-bottom)); display: flex; flex-direction: column; align-items: flex-end; gap: 11px; }
.weapon-card { display: flex; align-items: center; gap: 10px; padding: 8px 10px; background: linear-gradient(90deg, rgba(4,11,12,.2), rgba(4,11,12,.72)); border: 1px solid rgba(255,255,255,.1); }
.weapon-icon { width: calc(31px * var(--hud-scale)); height: calc(25px * var(--hud-scale)); display: grid; place-items: center; font-size: calc(17px * var(--hud-scale)); color: var(--gold); background: rgba(0,0,0,.32); border-radius: 2px; }
.weapon-info span { display: block; font-size: calc(5.5px * var(--hud-scale)); letter-spacing: .15em; color: var(--muted); }
.weapon-info b { font-family: 'Barlow Condensed'; font-size: calc(18px * var(--hud-scale)); font-weight: 700; line-height: 1; }
.weapon-info b small { font-family: 'Outfit'; font-size: calc(7px * var(--hud-scale)); font-weight: 400; color: var(--muted-2); }
.reload-btn { width: 22px; height: 22px; border: 1px solid rgba(255,255,255,.16); border-radius: 50%; color: var(--muted); font-size: 11px; padding: 0; }
.control-hint { display: flex; gap: 9px; font-size: 6.5px; color: rgba(255,255,255,.38); }
.control-hint span { display: flex; align-items: center; gap: 4px; }

.dialogue { position: absolute; left: 50%; bottom: calc(155px + var(--safe-bottom)); transform: translate(-50%, 16px); width: min(640px, 64vw); display: none; gap: 12px; padding: 15px 17px; background: linear-gradient(100deg, rgba(4,12,13,.95), rgba(7,18,20,.82)); border-left: 2px solid var(--coral); box-shadow: 0 16px 50px rgba(0,0,0,.5); backdrop-filter: blur(12px); pointer-events: auto; z-index: 12; }
.dialogue.on { display: flex; animation: dialogueIn .35s cubic-bezier(.2,.8,.2,1) both; }
.dialogue-portrait { flex: 0 0 46px; height: 46px; border-radius: 50%; display: grid; place-items: center; font-family: 'Barlow Condensed'; font-size: 23px; font-weight: 800; color: #ffd4c8; background: linear-gradient(145deg, #602c36, #1c171f); border: 1px solid rgba(255,112,88,.4); }
.dialogue-portrait.carlos { color: #bbfff1; background: linear-gradient(145deg, #1d4e48, #101d22); border-color: rgba(67,221,190,.4); }
.dialogue-body { flex: 1; }
.dialogue-top { display: flex; justify-content: space-between; }
.dialogue-top b { font-family: 'Barlow Condensed'; font-size: 12px; letter-spacing: .14em; color: var(--gold); }
.dialogue-top span { font-size: 6px; letter-spacing: .12em; color: var(--muted-2); }
.dialogue-body p { font-size: 12px; line-height: 1.55; color: #e9f2ee; margin-top: 4px; }
.dialogue-hint { display: flex; align-items: center; gap: 5px; margin-top: 8px; font-size: 7px; color: var(--muted-2); letter-spacing: .06em; }
.dialogue-hint i { font-style: normal; margin-left: auto; }
.interaction-prompt { position: absolute; left: 50%; bottom: calc(112px + var(--safe-bottom)); transform: translateX(-50%); display: none; align-items: center; gap: 10px; padding: 7px 12px 7px 8px; background: rgba(3,10,11,.9); border: 1px solid rgba(255,255,255,.14); border-radius: 4px; pointer-events: auto; }
.interaction-prompt.on { display: flex; animation: promptIn .2s both; }
.interaction-prompt .key { width: 25px; height: 25px; display: grid; place-items: center; background: var(--paper); color: #0a1516; border-radius: 3px; font-size: 10px; font-weight: 700; }
.interaction-prompt b { display: block; font-size: 8px; letter-spacing: .08em; }
.interaction-prompt small { display: block; font-size: 6.5px; color: var(--muted); margin-top: 1px; }
.subtitle-toast { position: absolute; left: 50%; bottom: calc(80px + var(--safe-bottom)); transform: translateX(-50%); padding: 8px 14px; background: rgba(3,9,10,.7); color: rgba(255,255,255,.8); font-size: 8px; letter-spacing: .03em; display: none; }
.subtitle-toast.on { display: block; }
.notifications { position: absolute; right: calc(28px + var(--safe-right)); top: calc(165px + var(--safe-top)); display: flex; flex-direction: column; gap: 5px; align-items: flex-end; }
.notification { display: flex; align-items: center; gap: 8px; padding: 7px 10px; background: rgba(3,10,11,.82); border-right: 2px solid var(--gold); font-size: 8px; color: #d6e4df; animation: notifIn .3s both; }
.notification i { color: var(--gold); font-style: normal; }
.hud-toast { position: absolute; left: 50%; top: 29%; transform: translateX(-50%); display: none; text-align: center; color: var(--gold); font-family: 'Barlow Condensed'; font-size: 19px; letter-spacing: .14em; text-shadow: 0 2px 12px #000; }
.hud-toast.on { display: block; animation: toastIn 2.4s both; }
.mobile-controls { display: none; }
.switch-character { position: absolute; right: calc(29px + var(--safe-right)); bottom: calc(116px + var(--safe-bottom)); display: flex; align-items: center; gap: 7px; padding: 4px 9px 4px 4px; background: rgba(4,11,12,.6); border: 1px solid rgba(255,255,255,.12); border-radius: 30px; color: #dfe9e5; }
.avatar-small { width: 24px; height: 24px; border-radius: 50%; display: grid; place-items: center; background: linear-gradient(135deg, #234f48, #0c1d21); color: #baffef; font-size: 9px; font-weight: 600; }
.switch-character b { display: block; font-size: 7px; letter-spacing: .1em; text-align: left; }
.switch-character small { display: block; font-size: 5.5px; color: var(--muted-2); text-align: left; }
.pause-button { position: absolute; left: 50%; top: calc(20px + var(--safe-top)); transform: translateX(-50%); display: none; }

/* ================= OVERLAYS SHARED ================= */
.overlay { position: absolute; inset: 0; z-index: 45; display: none; background: rgba(1,7,8,.72); backdrop-filter: blur(10px); }
.overlay.on { display: flex; }
.round-close { width: 35px; height: 35px; border-radius: 50%; border: 1px solid rgba(255,255,255,.2); color: var(--paper); font-size: 12px; display: grid; place-items: center; background: rgba(255,255,255,.05); }
.round-close:hover { background: var(--paper); color: #071416; }

/* ================= MAP ================= */
.map-overlay { z-index: 44; flex-direction: column; padding: 25px 30px; background: rgba(2,9,10,.92); }
