.lg-player { background: var(--teal); box-shadow: 0 0 6px var(--teal); }
.lg-mission { background: var(--gold); }
.lg-shop { background: var(--coral); }
.lg-police { background: #5d8dff; }
.map-stage { position: relative; flex: 1; display: flex; align-items: center; justify-content: center; padding-top: 16px; min-height: 0; }
