.map-meta { display: flex; justify-content: space-between; font-size: 7px; color: var(--muted); margin-top: 9px; padding-top: 8px; border-top: 1px solid rgba(255,255,255,.08); }
.map-meta b { color: var(--gold); font-weight: 500; }
.map-side-list { flex: 1; overflow-y: auto; }
.map-marker-row { display: flex; align-items: center; gap: 8px; padding: 7px 0; border-bottom: 1px solid rgba(255,255,255,.06); font-size: 8px; color: var(--muted); }
.map-marker-row i { width: 6px; height: 6px; background: var(--gold); border-radius: 50%; }
.map-marker-row b { flex: 1; color: #d6e4df; font-weight: 400; }
.map-marker-row span { font-size: 6.5px; color: var(--muted-2); }
.btn.full { width: 100%; }

/* ================= PAUSE ================= */
.pause-menu { z-index: 47; align-items: center; justify-content: center; padding: 2.5vh 3vw; }
.pause-bg { position: absolute; inset: 0; background: radial-gradient(ellipse at 50% 40%, rgba(24,66,60,.5), rgba(2,9,10,.92) 70%); }
.pause-card { position: relative; width: min(1110px, 94vw); height: min(780px, 94vh); background: linear-gradient(145deg, rgba(8,23,25,.97), rgba(4,13,15,.98)); border: 1px solid rgba(255,255,255,.13); border-radius: 8px; box-shadow: var(--shadow); display: flex; flex-direction: column; overflow: hidden; }
.pause-card::before { content: ''; position: absolute; inset: 0; background: radial-gradient(ellipse at 12% 0%, rgba(246,199,104,.06), transparent 45%); pointer-events: none; }
.pause-head { display: flex; align-items: center; justify-content: space-between; gap: 20px; padding: 20px 28px; border-bottom: 1px solid rgba(255,255,255,.08); position: relative; z-index: 1; }
.pause-head h1 { font-family: 'Barlow Condensed'; font-size: 30px; font-weight: 700; letter-spacing: .04em; margin-top: 3px; }
.pause-head h1 em { font-style: normal; color: var(--gold); }
.pause-profile { display: flex; align-items: center; gap: 10px; margin-left: auto; }
.pause-profile > span { width: 32px; height: 32px; border-radius: 50%; display: grid; place-items: center; background: linear-gradient(135deg, #24534b, #0b1d21); color: #bafff0; font-size: 10px; border: 1px solid rgba(67,221,190,.3); }
.pause-profile b { display: block; font-size: 9px; letter-spacing: .06em; }
.pause-profile small { display: block; font-size: 7px; color: var(--muted-2); margin-top: 1px; }
.pause-body { flex: 1; display: grid; grid-template-columns: 170px 1fr; min-height: 0; position: relative; z-index: 1; }
.pause-tabs { padding: 22px 14px; border-right: 1px solid rgba(255,255,255,.07); display: flex; flex-direction: column; gap: 3px; }
.pause-tabs button { text-align: left; padding: 10px 12px; border-radius: 4px; font-size: 9px; letter-spacing: .06em; color: var(--muted); border-left: 2px solid transparent; }
.pause-tabs button:hover { color: var(--paper); background: rgba(255,255,255,.04); }
.pause-tabs button.active { color: var(--gold); border-left-color: var(--gold); background: rgba(246,199,104,.07); }
.pause-panel { display: none; padding: 24px 28px; overflow-y: auto; min-height: 0; scrollbar-width: thin; scrollbar-color: rgba(255,255,255,.15) transparent; }
.pause-panel.active { display: block; }
.pause-panel::-webkit-scrollbar { width: 4px; } .pause-panel::-webkit-scrollbar-thumb { background: rgba(255,255,255,.16); }
.pause-hero { display: grid; grid-template-columns: 36% 1fr; gap: 25px; height: 100%; align-items: center; }
.pause-hero-art { height: min(360px, 47vh); border: 1px solid rgba(255,255,255,.15); position: relative; background: linear-gradient(160deg, #c66550 0%, #63333f 45%, #142b2e 100%); overflow: hidden; border-radius: 3px; }
.pause-hero-art::before { content: ''; position: absolute; inset: 0; background: radial-gradient(circle at 67% 27%, #ffe5a8 0 8%, transparent 9%), linear-gradient(180deg, transparent 52%, rgba(3,10,11,.6) 53%, #071416); box-shadow: inset 0 0 60px rgba(0,0,0,.3); }
.pause-hero-art::after { content: ''; position: absolute; left: 0; right: 0; bottom: 0; height: 42%; background: repeating-linear-gradient(172deg, transparent 0 7px, rgba(255,178,125,.12) 8px, transparent 9px 18px); }
.pause-hero-art span { position: absolute; left: 17px; bottom: 16px; z-index: 2; font-family: 'Barlow Condensed'; font-size: 39px; font-weight: 800; line-height: .82; letter-spacing: .02em; color: rgba(255,255,255,.94); }
.pause-hero-art i { position: absolute; right: 14px; top: 14px; width: 37px; height: 37px; border: 1px solid rgba(255,255,255,.42); border-radius: 50%; z-index: 2; }
.pause-hero-info .eyebrow { margin-bottom: 5px; }
.pause-hero-info h2 { font-family: 'Barlow Condensed'; font-size: clamp(23px, 2.4vw, 34px); font-weight: 700; letter-spacing: .03em; }
.pause-hero-info > p:not(.eyebrow) { font-size: 9px; line-height: 1.5; color: var(--muted); margin-top: 7px; max-width: 430px; }
.pause-stats { display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px; margin: 22px 0; border-top: 1px solid rgba(255,255,255,.1); border-bottom: 1px solid rgba(255,255,255,.1); padding: 13px 0; }
.pause-stats span { display: block; font-size: 6.5px; letter-spacing: .11em; color: var(--muted-2); }
.pause-stats b { display: block; font-family: 'Barlow Condensed'; font-size: 17px; font-weight: 600; margin-top: 3px; color: #e4eeea; }
.panel-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 15px; margin-bottom: 17px; }
.panel-head h2 { font-family: 'Barlow Condensed'; font-size: 27px; font-weight: 700; letter-spacing: .02em; margin-top: 3px; }
#mission-count-badge, .settings-autosave { font-size: 7px; letter-spacing: .1em; color: var(--muted-2); border: 1px solid rgba(255,255,255,.1); padding: 5px 8px; border-radius: 3px; }
.mission-list { display: flex; flex-direction: column; gap: 6px; }
.mission-row { display: grid; grid-template-columns: 35px 1fr auto auto; align-items: center; gap: 11px; padding: 11px 13px; border: 1px solid rgba(255,255,255,.08); background: rgba(255,255,255,.02); border-radius: 3px; }
.mission-row.completed { border-color: rgba(67,221,190,.15); }
.mission-row.active { border-color: rgba(246,199,104,.32); background: rgba(246,199,104,.04); }
.mission-row.locked { opacity: .38; }
.mission-num { width: 27px; height: 27px; border-radius: 50%; display: grid; place-items: center; font-family: 'Barlow Condensed'; font-size: 12px; border: 1px solid rgba(255,255,255,.18); color: var(--muted); }
.mission-row.completed .mission-num { background: rgba(67,221,190,.12); border-color: rgba(67,221,190,.4); color: var(--teal); }
.mission-row.active .mission-num { background: var(--gold); border-color: var(--gold); color: #1a1205; }
.mission-row h4 { font-size: 10px; font-weight: 500; letter-spacing: .02em; }
.mission-row p { font-size: 7.5px; color: var(--muted-2); margin-top: 2px; }
.mission-row .m-protag { font-size: 6px; letter-spacing: .1em; color: var(--gold); border: 1px solid rgba(246,199,104,.2); padding: 3px 5px; }
.mission-row button { font-size: 7px; color: var(--muted); border: 1px solid rgba(255,255,255,.13); padding: 4px 8px; border-radius: 2px; }
.mission-row button:hover { color: var(--gold); border-color: var(--gold); }
.settings-container { display: flex; flex-direction: column; gap: 13px; }
.settings-section { border: 1px solid rgba(255,255,255,.08); border-radius: 4px; overflow: hidden; }
.settings-section-head { display: flex; justify-content: space-between; align-items: center; padding: 10px 13px; background: rgba(255,255,255,.025); border-bottom: 1px solid rgba(255,255,255,.07); }
.settings-section-head h4 { font-size: 9px; font-weight: 500; letter-spacing: .08em; color: #dce8e3; }
.settings-section-head span { font-size: 6.5px; color: var(--gold); letter-spacing: .08em; }
.settings-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 0 20px; padding: 5px 13px 8px; }
.setting-row { display: flex; align-items: center; justify-content: space-between; gap: 10px; min-height: 37px; border-bottom: 1px solid rgba(255,255,255,.055); }
.setting-row:last-child { border-bottom: 0; }
.setting-label b { display: block; font-size: 8px; font-weight: 400; color: #d4e1dc; }
.setting-label small { display: block; font-size: 6px; color: var(--muted-2); margin-top: 1px; }
.setting-control { display: flex; align-items: center; gap: 4px; flex-shrink: 0; }
.seg { display: flex; border: 1px solid rgba(255,255,255,.11); border-radius: 2px; overflow: hidden; }
.seg button { padding: 4px 7px; font-size: 6.5px; color: var(--muted); background: transparent; border-right: 1px solid rgba(255,255,255,.07); }
.seg button:last-child { border-right: 0; }
.seg button.active { background: var(--gold); color: #171005; font-weight: 600; }
input[type=range] { -webkit-appearance: none; appearance: none; width: 84px; height: 3px; background: rgba(255,255,255,.13); border-radius: 4px; outline: 0; }
input[type=range]::-webkit-slider-thumb { -webkit-appearance: none; width: 10px; height: 10px; border-radius: 50%; background: var(--gold); box-shadow: 0 0 0 3px rgba(246,199,104,.14); cursor: pointer; }
input[type=range]::-moz-range-thumb { width: 10px; height: 10px; border: 0; border-radius: 50%; background: var(--gold); cursor: pointer; }
.range-val { font-size: 7px; color: var(--gold); min-width: 26px; text-align: right; }
.toggle { position: relative; width: 27px; height: 14px; border-radius: 10px; background: rgba(255,255,255,.13); border: 1px solid rgba(255,255,255,.1); }
.toggle::after { content: ''; position: absolute; width: 9px; height: 9px; border-radius: 50%; background: rgba(255,255,255,.55); top: 2px; left: 2px; transition: .2s; }
.toggle.on { background: rgba(67,221,190,.35); border-color: rgba(67,221,190,.35); }
.toggle.on::after { left: 14px; background: var(--teal); }
.settings-note { grid-column: 1 / -1; display: flex; align-items: center; gap: 8px; padding: 8px 10px; margin: 4px 0 7px; border: 1px dashed rgba(246,199,104,.2); font-size: 6.5px; line-height: 1.5; color: var(--muted); }
.settings-note b { color: var(--gold); font-weight: 500; }
.controls-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 5px 22px; }
.control-row { display: flex; justify-content: space-between; align-items: center; border-bottom: 1px solid rgba(255,255,255,.06); padding: 8px 0; font-size: 8px; color: var(--muted); }
.control-row b { font-weight: 400; color: #d5e2dd; }
.control-row .keys { display: flex; gap: 3px; }
.save-panel { display: grid; grid-template-columns: 220px 1fr; gap: 22px; align-items: start; }
.save-art { height: 260px; border: 1px solid rgba(255,255,255,.13); background: linear-gradient(150deg, #cc6e55, #63343f 45%, #10272b); position: relative; display: flex; flex-direction: column; justify-content: flex-end; padding: 16px; overflow: hidden; }
.save-art::before { content: ''; position: absolute; inset: 0; background: radial-gradient(circle at 65% 30%, #ffe3a4 0 8%, transparent 9%), linear-gradient(180deg, transparent 55%, rgba(0,0,0,.6)); }
.save-art span { position: absolute; top: 14px; right: 14px; width: 36px; height: 36px; border: 1px solid rgba(255,255,255,.35); border-radius: 50%; display: grid; place-items: center; font-size: 9px; }
.save-art b { position: relative; font-family: 'Barlow Condensed'; font-size: 24px; letter-spacing: .03em; }
.save-art small { position: relative; font-size: 6px; letter-spacing: .18em; color: var(--gold); margin-top: 2px; }
.save-info p { font-size: 9px; line-height: 1.65; color: var(--muted); max-width: 420px; }
.save-status { display: flex; justify-content: space-between; padding: 10px 0; margin: 17px 0 14px; border-top: 1px solid rgba(255,255,255,.1); border-bottom: 1px solid rgba(255,255,255,.1); font-size: 8px; color: var(--muted); }
.save-status b { color: var(--teal); font-weight: 500; }
.save-info .btn { width: 100%; margin-bottom: 7px; }
.pause-footer { display: flex; justify-content: space-between; padding: 12px 28px; border-top: 1px solid rgba(255,255,255,.07); font-size: 6.5px; letter-spacing: .12em; color: var(--muted-2); position: relative; z-index: 1; }

/* ================= PHONE ================= */
.phone-overlay { z-index: 43; align-items: center; justify-content: center; background: rgba(1,6,7,.62); }
.phone-device { position: relative; width: min(335px, 84vw); height: min(690px, 92vh); border-radius: 38px; padding: 12px; background: linear-gradient(145deg, #1c3134, #071112); border: 1px solid rgba(255,255,255,.2); box-shadow: 0 30px 100px rgba(0,0,0,.7), inset 0 0 0 1px rgba(0,0,0,.6); }
.phone-notch { position: absolute; top: 18px; left: 50%; transform: translateX(-50%); width: 80px; height: 18px; border-radius: 20px; background: #000; z-index: 3; }
.phone-screen { position: relative; height: 100%; border-radius: 28px; background: radial-gradient(circle at 50% -10%, #16383a, #081819 55%); overflow: hidden; padding: 20px 17px 12px; display: flex; flex-direction: column; }
.phone-status { display: flex; justify-content: space-between; font-size: 8px; color: rgba(255,255,255,.65); padding: 0 4px 14px; }
.phone-head { display: flex; justify-content: space-between; align-items: flex-start; }
.phone-head small { font-size: 7px; letter-spacing: .16em; color: var(--gold); }
.phone-head h3 { font-family: 'Barlow Condensed'; font-size: 25px; font-weight: 700; letter-spacing: .04em; margin-top: 2px; }
.rp-online { display: flex; align-items: center; gap: 5px; font-size: 6.5px; letter-spacing: .1em; color: var(--teal); padding: 4px 7px; border: 1px solid rgba(67,221,190,.25); border-radius: 20px; }
.rp-online i { width: 4px; height: 4px; border-radius: 50%; background: var(--teal); }
.phone-wallet { margin-top: 12px; padding: 14px; border-radius: 10px; background: linear-gradient(135deg, rgba(246,199,104,.16), rgba(67,221,190,.07)); border: 1px solid rgba(246,199,104,.18); position: relative; overflow: hidden; }
.phone-wallet::after { content: ''; position: absolute; width: 100px; height: 100px; border-radius: 50%; background: rgba(246,199,104,.08); right: -30px; top: -45px; }
.phone-wallet span { display: block; font-size: 6px; letter-spacing: .18em; color: var(--muted); }
.phone-wallet b { display: block; font-family: 'Barlow Condensed'; font-size: 29px; color: var(--gold); margin-top: 3px; line-height: 1; }
.phone-wallet small { display: block; font-size: 6.5px; color: var(--teal); margin-top: 5px; letter-spacing: .12em; }
.phone-apps { display: flex; flex-direction: column; gap: 6px; margin-top: 14px; }
.app-card { display: flex; align-items: center; gap: 10px; padding: 9px 10px; border: 1px solid rgba(255,255,255,.08); border-radius: 7px; background: rgba(255,255,255,.035); text-align: left; }
.app-card.active { border-color: rgba(246,199,104,.3); background: rgba(246,199,104,.06); }
.app-icon { width: 30px; height: 30px; border-radius: 8px; display: grid; place-items: center; background: rgba(67,221,190,.12); color: var(--teal); font-size: 14px; }
.app-card:nth-child(2) .app-icon { color: var(--gold); background: rgba(246,199,104,.1); }
.app-card:nth-child(3) .app-icon { color: var(--coral); background: rgba(255,112,88,.1); }
.app-card:nth-child(4) .app-icon { color: #b6a1ff; background: rgba(166,139,255,.1); }
.app-card div { flex: 1; }
.app-card b { display: block; font-size: 9px; font-weight: 500; }
.app-card small { display: block; font-size: 6.5px; color: var(--muted-2); margin-top: 1px; }
.app-card i { font-style: normal; color: var(--muted-2); font-size: 11px; }
.phone-job-info { flex: 1; margin-top: 12px; padding-top: 12px; border-top: 1px solid rgba(255,255,255,.08); }
.phone-job-info h4 { font-family: 'Barlow Condensed'; font-size: 18px; font-weight: 600; margin-top: 3px; }
.phone-job-info p:not(.eyebrow) { font-size: 7.5px; line-height: 1.55; color: var(--muted); margin-top: 5px; }
.phone-start { width: 100%; padding: 10px; margin-top: 11px; background: var(--gold); color: #1c1306; font-size: 8px; letter-spacing: .07em; font-weight: 600; border-radius: 4px; }
.phone-footer { display: flex; justify-content: space-around; padding: 11px 0 2px; border-top: 1px solid rgba(255,255,255,.06); font-size: 11px; color: var(--muted-2); }
.phone-close { position: absolute; right: -47px; top: 4px; width: 34px; height: 34px; border-radius: 50%; background: rgba(255,255,255,.1); border: 1px solid rgba(255,255,255,.2); font-size: 12px; }
.phone-device .phone-close { right: -5px; top: -5px; z-index: 5; background: #0c1b1d; }

/* ================= MISSION CARD ================= */
.mission-card { position: absolute; inset: 0; z-index: 42; display: none; background: #071416; overflow: hidden; }
.mission-card.on { display: block; animation: missionIn .75s both; }
.mission-card-bg { position: absolute; inset: 0; background: linear-gradient(110deg, #0b2c31 0%, #3e3437 45%, #ba6b54 80%, #0a1c20 100%); }
.mission-card-bg::before { content: ''; position: absolute; inset: 0; background: radial-gradient(circle at 70% 42%, rgba(255,213,145,.4), transparent 25%), linear-gradient(180deg, transparent 50%, rgba(3,10,11,.7)); }
.mission-card-bg::after { content: ''; position: absolute; inset: 0; background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 120 120' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='a'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.85' numOctaves='2'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23a)' opacity='.18'/%3E%3C/svg%3E"); mix-blend-mode: overlay; }
.mission-card::after { content: ''; position: absolute; inset: 0; background: linear-gradient(90deg, rgba(3,10,11,.84), rgba(3,10,11,.12) 60%, rgba(3,10,11,.5)), linear-gradient(0deg, rgba(3,10,11,.9), transparent 55%); }
.mission-card-index { position: absolute; left: 7vw; top: 17vh; z-index: 2; display: flex; flex-direction: column; }
.mission-card-index span { font-family: 'Barlow Condensed'; font-size: clamp(92px, 14vw, 210px); font-weight: 800; line-height: .8; color: var(--gold); opacity: .95; }
.mission-card-index small { font-size: 8px; letter-spacing: .5em; color: rgba(255,255,255,.6); margin-top: 17px; }
.mission-card-copy { position: absolute; left: 7vw; bottom: 17vh; z-index: 2; max-width: 720px; }
.mission-card-copy h1 { font-family: 'Barlow Condensed'; font-size: clamp(47px, 6.4vw, 100px); font-weight: 800; line-height: .85; margin-top: 13px; letter-spacing: .01em; }
.mission-card-copy > p:not(.eyebrow) { font-size: 11px; color: rgba(236,243,238,.65); margin-top: 15px; letter-spacing: .02em; }
.mission-card-side { position: absolute; right: 5vw; bottom: 9vh; z-index: 2; display: flex; gap: 11px; align-items: center; font-size: 6.5px; letter-spacing: .2em; color: rgba(255,255,255,.4); writing-mode: vertical-rl; }
.mission-card-side i { width: 1px; height: 36px; background: rgba(246,199,104,.4); }
@keyframes missionIn { from { opacity: 0; filter: blur(10px); transform: scale(1.02); } to { opacity: 1; filter: none; transform: none; } }

/* ================= MISSION COMPLETE ================= */
.mission-complete { z-index: 46; align-items: center; justify-content: center; background: radial-gradient(ellipse at center, rgba(8,38,36,.7), rgba(1,7,8,.94)); }
.complete-card { width: min(490px, 88vw); text-align: center; padding: 33px 35px; border: 1px solid rgba(246,199,104,.28); background: linear-gradient(160deg, rgba(9,27,29,.97), rgba(4,13,15,.98)); box-shadow: var(--shadow); position: relative; }
.complete-card::before { content: ''; position: absolute; inset: 8px; border: 1px solid rgba(255,255,255,.06); pointer-events: none; }
.complete-card h1 { font-family: 'Barlow Condensed'; font-size: clamp(34px, 4vw, 52px); font-weight: 800; margin-top: 10px; letter-spacing: .02em; }
.complete-stars { color: var(--gold); letter-spacing: .15em; font-size: 20px; margin-top: 7px; text-shadow: 0 0 18px rgba(246,199,104,.4); }
.complete-reward { display: flex; align-items: center; justify-content: space-between; margin-top: 22px; padding: 12px 0; border-top: 1px solid rgba(255,255,255,.1); border-bottom: 1px solid rgba(255,255,255,.1); font-size: 8px; letter-spacing: .12em; color: var(--muted); }
.complete-reward b { font-family: 'Barlow Condensed'; font-size: 27px; color: var(--teal); font-weight: 700; }
.complete-stats { display: grid; grid-template-columns: repeat(3,1fr); gap: 6px; margin: 15px 0 22px; }
.complete-stats div { padding: 8px; background: rgba(255,255,255,.03); }
.complete-stats span { display: block; font-size: 5.5px; letter-spacing: .1em; color: var(--muted-2); }
.complete-stats b { display: block; font-size: 11px; font-weight: 500; margin-top: 3px; color: #dce8e3; }

/* ================= WASTED ================= */
.wasted-screen { z-index: 48; align-items: center; justify-content: center; background: rgba(24,4,4,.41); }
.wasted-shade { position: absolute; inset: 0; background: radial-gradient(ellipse at center, transparent, rgba(40,3,3,.7)); }
.wasted-copy { position: relative; text-align: center; }
.wasted-copy h1 { font-family: 'Barlow Condensed'; font-size: clamp(68px, 12vw, 150px); font-weight: 800; letter-spacing: -.01em; color: #f4efea; line-height: .8; margin: 13px 0; text-shadow: 0 10px 50px rgba(0,0,0,.5); }
.wasted-copy h1 span { color: var(--coral); }
.wasted-copy p:not(.eyebrow) { font-size: 10px; color: rgba(240,230,225,.55); letter-spacing: .04em; }
.wasted-options { display: flex; gap: 8px; margin-top: 28px; justify-content: center; }

.toast-layer { position: absolute; top: calc(24px + var(--safe-top)); left: 50%; transform: translateX(-50%); z-index: 55; display: flex; flex-direction: column; gap: 6px; align-items: center; pointer-events: none; }
.system-toast { padding: 9px 14px; background: rgba(4,13,15,.96); border: 1px solid rgba(255,255,255,.14); border-left: 2px solid var(--teal); font-size: 8px; letter-spacing: .05em; color: #e0ebe6; box-shadow: 0 10px 30px rgba(0,0,0,.4); animation: notifIn .25s both; }
.system-toast.warn { border-left-color: var(--gold); }
.system-toast.danger { border-left-color: var(--coral); }
.rotate-hint { position: fixed; inset: 0; z-index: 90; display: none; place-items: center; background: #061214; text-align: center; }
.rotate-hint div { font-size: 38px; color: var(--gold); animation: spin 3s linear infinite; }
.rotate-hint p { font-size: 11px; color: var(--muted); }

@keyframes pulse { 50% { opacity: .3; } }
@keyframes dangerPulse { to { opacity: .55; } }
@keyframes hit { 0% { opacity: 1; transform: translate(-50%,-50%) scale(.7); } 100% { opacity: 0; transform: translate(-50%,-50%) scale(1.4); } }
@keyframes lowHealth { 50% { opacity: .45; } }
@keyframes dialogueIn { from { opacity: 0; transform: translate(-50%, 12px); } to { opacity: 1; transform: translate(-50%, 0); } }
@keyframes promptIn { from { opacity: 0; transform: translate(-50%, 7px); } to { opacity: 1; transform: translate(-50%, 0); } }
@keyframes notifIn { from { opacity: 0; transform: translateX(12px); } to { opacity: 1; transform: none; } }
@keyframes toastIn { 0% { opacity: 0; transform: translate(-50%, 10px); } 15%,75% { opacity: 1; transform: translate(-50%,0); } 100% { opacity: 0; transform: translate(-50%,-5px); } }

/* ================= RESPONSIVE ================= */
@media (max-width: 1120px) {
  .emu-layout { grid-template-columns: 184px 1fr; }
  .emu-main { padding-left: 3vw; padding-right: 3vw; }
  .emu-lower { grid-template-columns: 1fr 1fr; }
  .quick-panel { display: none; }
  .hero-content { width: 70%; }
  .menu-layout { grid-template-columns: minmax(400px, 60%) 1fr; }
  .menu-side { width: min(285px, 100%); }
  .objective-panel { width: 310px; }
}
