  .controls-grid { grid-template-columns: 1fr; }
  .pause-footer { padding: 9px 14px; }
  .pause-footer span:first-child { display: none; }
  .phone-device { width: min(335px, 90vw); height: min(690px, 88vh); }
  .complete-card { padding: 25px 20px; }
  .wasted-options { flex-direction: column; }
  .wasted-options .btn { min-width: 220px; }
  .boot-footer { left: 20px; right: 20px; font-size: 7px; }
}

/* ================= TOUCH / MOBILE HUD ================= */
body.touch .mobile-controls, body.force-touch .mobile-controls { display: block; }
body.touch .desktop-hint, body.force-touch .desktop-hint { display: none; }
body.touch #bottom-right, body.force-touch #bottom-right { bottom: calc(20px + var(--safe-bottom)); }
body.touch .switch-character, body.force-touch .switch-character { display: none; }
body.touch .pause-button, body.force-touch .pause-button { display: grid; place-items: center; width: 31px; height: 31px; border: 1px solid rgba(255,255,255,.23); border-radius: 50%; background: rgba(4,11,12,.62); color: #fff; font-size: 10px; }
body.touch .minimap-shell, body.force-touch .minimap-shell { width: calc(145px * var(--hud-scale)); height: calc(145px * var(--hud-scale)); }
body.touch #top-left, body.force-touch #top-left { top: calc(14px + var(--safe-top)); left: calc(14px + var(--safe-left)); }
body.touch #top-right, body.force-touch #top-right { top: calc(15px + var(--safe-top)); right: calc(14px + var(--safe-right)); }
body.touch .objective-panel, body.force-touch .objective-panel { top: auto; bottom: calc(215px + var(--safe-bottom)); width: min(330px, 72vw); padding: 8px 12px; }
body.touch .objective-panel h3, body.force-touch .objective-panel h3 { font-size: 15px; }
body.touch .objective-panel p, body.force-touch .objective-panel p { display: block; font-size: 7px; }
body.touch .objective-dist, body.force-touch .objective-dist { margin-top: 4px; }
body.touch #bottom-left, body.force-touch #bottom-left { bottom: calc(16px + var(--safe-bottom)); left: calc(14px + var(--safe-left)); transform: scale(calc(var(--hud-scale) * .86)); transform-origin: left bottom; }
body.touch .player-info, body.force-touch .player-info { width: 125px; }
body.touch .radio-row, body.force-touch .radio-row { display: none; }
body.touch .stamina-row, body.force-touch .stamina-row { display: none; }
body.touch #top-right .clock-weather, body.force-touch #top-right .clock-weather { display: none; }
body.touch .money-shell b, body.force-touch .money-shell b { font-size: 17px; }
body.touch .money-shell span, body.force-touch .money-shell span { display: none; }
body.touch .fps-badge, body.force-touch .fps-badge { display: none; }
