  const oceanUniforms = {
    uTime: { value: 0 },
    uDeep: { value: new THREE.Color(0x062238) },
    uShallow: { value: new THREE.Color(0x1d8f8d) },
    uFoam: { value: new THREE.Color(0xdff7ea) },
    uSunDir: { value: sunDir.clone() },
    uHorizon: { value: new THREE.Color(0xd88d73) },
    uShore: { value: WORLD.oceanZ }
  };
  const oceanMat = new THREE.ShaderMaterial({
    uniforms: oceanUniforms,
    side: THREE.DoubleSide,
    vertexShader: `
      uniform float uTime;
      varying vec3 vWorldPosition;
      varying vec3 vNormal;
      varying float vWave;
      varying float vCrest;
      float w1(vec2 p){ return sin(p.x * .045 + uTime * .62) * .85 + sin(p.y * .065 - uTime * .42 + 1.2) * .55; }
      float w2(vec2 p){ return sin(p.x * .022 - p.y * .031 + uTime * .33) * 1.15; }
      void main(){
        vec3 pos = position;
        float a = sin(pos.x * .052 + uTime * .68) * .6;
        float b = sin(pos.z * .074 - uTime * .53 + 1.4) * .38;
        float c = sin((pos.x + pos.z) * .023 + uTime * .34) * .9;
        float d = sin(pos.x * .16 + pos.z * .11 + uTime * 1.25) * .12;
        pos.y += a + b + c + d;
        float dx = cos(pos.x * .052 + uTime * .68) * .6 * .052 + cos((pos.x+pos.z) * .023 + uTime * .34) * .9 * .023 + cos(pos.x * .16 + pos.z*.11 + uTime*1.25)*.12*.16;
        float dz = sin(pos.z * .074 - uTime * .53 + 1.4) * .38 * .074 + cos((pos.x+pos.z) * .023 + uTime * .34) * .9 * .023 + cos(pos.x * .16 + pos.z*.11 + uTime*1.25)*.12*.11;
        vec3 n = normalize(vec3(-dx, 1.0, -dz));
        vNormal = normalize(mat3(modelMatrix) * n);
        vec4 wp = modelMatrix * vec4(pos, 1.0);
        vWorldPosition = wp.xyz;
        vWave = a + b + c;
        vCrest = d * 2.0 + c;
        gl_Position = projectionMatrix * viewMatrix * wp;
      }
    `,
    fragmentShader: `
      uniform float uTime;
      uniform vec3 uDeep; uniform vec3 uShallow; uniform vec3 uFoam; uniform vec3 uSunDir; uniform vec3 uHorizon; uniform float uShore;
      varying vec3 vWorldPosition; varying vec3 vNormal; varying float vWave; varying float vCrest;
      float hash(vec2 p){ return fract(sin(dot(p, vec2(127.1,311.7))) * 43758.5453); }
      float vnoise(vec2 p){ vec2 i=floor(p), f=fract(p); f=f*f*(3.0-2.0*f);
        return mix(mix(hash(i),hash(i+vec2(1.,0.)),f.x), mix(hash(i+vec2(0.,1.)),hash(i+vec2(1.,1.)),f.x),f.y); }
      void main(){
        vec3 viewDir = normalize(cameraPosition - vWorldPosition);
        vec3 N = normalize(vNormal);
        float shoreDist = clamp((vWorldPosition.z - uShore) / 150.0, 0.0, 1.0);
        vec3 base = mix(uShallow, uDeep, smoothstep(0.02, .6, shoreDist));
        base = mix(base, vec3(.055,.20,.26), smoothstep(.75, 1.0, shoreDist) * .5);
        float fres = pow(1.0 - max(dot(N, viewDir), 0.0), 3.4);
        vec3 refl = mix(uHorizon, vec3(.32,.47,.58), smoothstep(0.05, .6, abs(N.y)));
        vec3 color = mix(base, refl, fres * .72);
        vec3 R = reflect(-viewDir, N);
        float spec = pow(max(dot(R, normalize(uSunDir)), 0.0), 120.0);
        float broad = pow(max(dot(R, normalize(uSunDir)), 0.0), 10.0);
        color += vec3(1.0, .67, .38) * spec * 2.6 + vec3(1.0,.55,.3) * broad * .12;
        float sparkle = step(.982, vnoise(vWorldPosition.xz * 1.9 + uTime * .7));
        color += vec3(1.0,.86,.62) * sparkle * .9;
        float foamNoise = vnoise(vWorldPosition.xz * .25 + vec2(uTime*.2, -uTime*.17));
        float shoreFoam = smoothstep(.07, 0.0, shoreDist) * smoothstep(.34, .7, foamNoise + sin(vWorldPosition.x * .34 + uTime*1.7)*.25) * 1.4;
        float crest = smoothstep(1.25, 1.9, abs(vWave)) * .16;
        float lines = smoothstep(.85, .98, sin(vWorldPosition.z * .24 - uTime * .8 + vWorldPosition.x * .08) * .5 + .5);
        color = mix(color, uFoam, clamp(shoreFoam + crest + lines * .02, 0.0, .9));
        float alpha = .98;
        float fog = smoothstep(280.0, 760.0, distance(cameraPosition, vWorldPosition));
        color = mix(color, uHorizon * .8, fog * .65);
        gl_FragColor = vec4(color, alpha);
      }
    `
  });
  const oceanGeo = new THREE.PlaneGeometry(1500, 920, quality === 'performance' ? 80 : 128, quality === 'performance' ? 45 : 74);
  oceanGeo.rotateX(-Math.PI / 2);
  const ocean = new THREE.Mesh(oceanGeo, oceanMat);
  ocean.position.set(0, -0.55, 600);
  scene.add(ocean);
  world.ocean = ocean;
  world.oceanUniforms = oceanUniforms;

  // island silhouettes
  for (const [ix, iz, s] of [[300, 420, 1], [-245, 520, 1.5], [520, 650, 1.8]]) {
    const island = new THREE.Group();
    const rock = new THREE.Mesh(new THREE.ConeGeometry(50, 25, 9), new THREE.MeshStandardMaterial({ color: 0x244d42, roughness: 1, flatShading: true }));
    rock.position.y = 9; island.add(rock);
    for (let i = 0; i < 5; i++) {
      const tree = new THREE.Mesh(new THREE.ConeGeometry(5 + rand() * 8, 15 + rand() * 10, 6), new THREE.MeshStandardMaterial({ color: 0x1f5c45, roughness: 1 }));
      tree.position.set(-15 + rand() * 30, 22 + rand() * 6, -10 + rand() * 20); island.add(tree);
    }
    island.position.set(ix, -.6, iz); island.scale.setScalar(s); scene.add(island);
  }

  // ---------------- NPC SPAWNS ----------------
  const firstNames = ['Rafa', 'Bia', 'Duda', 'Tati', 'Nando', 'Júlia', 'Caio', 'Mila', 'Diego', 'Léo', 'Sofia', 'Igor', 'Nina', 'Tom', 'Cris', 'Vini', 'Aline', 'Rui'];
  for (let i = 0; i < 26; i++) {
    const onBeach = i < 13;
    world.npcSpawns.push({
      x: onBeach ? -380 + rand() * 760 : -330 + rand() * 650,
      z: onBeach ? 112 + rand() * 24 : 92 + rand() * 12,
      name: pick(firstNames),
      walking: true,
      axis: rand() > .5 ? 'x' : 'z'
    });
  }
  for (let i = 0; i < 9; i++) {
    world.npcSpawns.push({ x: -280 + rand() * 560, z: -330 + rand() * 260, name: pick(firstNames), walking: false });
  }

  // ---------------- VEHICLE SPAWNS ----------------
  const carColors = [0xf1eee3, 0xd6594e, 0x2c8d8b, 0xefb94e, 0x2d6da3, 0x7d4c8c, 0x343a3c, 0xc37b4e];
  for (let i = 0; i < 10; i++) {
    const alongBeach = i < 5;
    world.vehicleSpawns.push({
      x: alongBeach ? -330 + i * 135 : -300 + rand() * 600,
      z: alongBeach ? 76.5 : -300 + rand() * 340,
      rotY: alongBeach ? Math.PI / 2 : (rand() > .5 ? Math.PI / 2 : 0),
      color: pick(carColors),
      type: pick(['hatch', 'muscle', 'pickup', 'suv', 'van'])
    });
  }
  world.vehicleSpawns.push({ x: -76, z: 70, rotY: Math.PI / 2, color: 0xff7058, type: 'muscle', hero: true });
  world.vehicleSpawns.push({ x: 102, z: 40, rotY: 0, color: 0x53b8b1, type: 'suv', hero: true });

  // ---------------- NPC GATHERING SPOTS / LOCATIONS ----------------
  world.locations.club = new THREE.Vector3(187, 0, -26);
  world.locations.hospital = new THREE.Vector3(-36, 0, -58);
  world.locations.garage = new THREE.Vector3(126, 0, -6);
  world.locations.beachKiosk = new THREE.Vector3(-62, 0, 95.5);
  world.locations.pier = new THREE.Vector3(108, 0, 202);
  world.locations.matteoTower = new THREE.Vector3(17, 0, -224);
  world.locations.delivery = new THREE.Vector3(-350, 0, -228);
  world.locations.marina = new THREE.Vector3(290, 0, 25);
  world.locations.ferris = new THREE.Vector3(350, 0, 35);
  world.locations.park = new THREE.Vector3(-178, 0, 30);
  world.locations.favela = new THREE.Vector3(-350, 0, -222);

  // add invisible colliders for lighthouse base etc done. Keep player on land side.
  world.bounds = { minX: -430, maxX: 430, minZ: -410, maxZ: 150 };

  // Add under-city environment sign props, bus stops
  const busStops = [-190, 30, 260];
  busStops.forEach(x => {
    const g = new THREE.Group();
    const glass = new THREE.Mesh(new THREE.BoxGeometry(5, 2.7, 1.4), new THREE.MeshPhysicalMaterial({ color: 0x84c5c2, roughness: .12, metalness: .2, transparent: true, opacity: .3 }));
    glass.position.y = 1.7; g.add(glass);
    const roof = new THREE.Mesh(new THREE.BoxGeometry(5.4, .18, 2), new THREE.MeshStandardMaterial({ color: 0x304447, metalness: .4, roughness: .6 }));
    roof.position.y = 3.1; g.add(roof);
    const sign = new THREE.Mesh(new THREE.PlaneGeometry(2.6, .6), new THREE.MeshBasicMaterial({ map: makeTextTexture('COSTA BUS', { width: 512, height: 128, font: '700 58px "Barlow Condensed", sans-serif', padding: 24, bg: '#1b3434', color: '#baffef', accent: '#43ddbe', sub: '' }), toneMapped: false }));
    sign.position.set(0, 2.45, .72); g.add(sign);
    g.position.set(x, 0, 90.2); g.rotation.y = Math.PI;
    scene.add(g);
  });

  // floating dust / seagulls
  const gullGeo = new THREE.BufferGeometry();
  const gp = [];
  for (let i = 0; i < 32; i++) {
    const x = -300 + rand() * 600, y = 24 + rand() * 45, z = 80 + rand() * 300;
    gp.push(x - .7, y, z, x, y + .22, z, x + .7, y, z);
  }
  gullGeo.setAttribute('position', new THREE.Float32BufferAttribute(gp, 3));
  const gulls = new THREE.LineSegments(gullGeo, new THREE.LineBasicMaterial({ color: 0x263638, transparent: true, opacity: .6 }));
  scene.add(gulls);
  world.animate.push((dt, t) => { gulls.position.x = Math.sin(t * .06) * 12; gulls.position.y = Math.sin(t * .16) * 1.5; });

  // eucalyptus / leaf scent details: small rocks and beach debris
  const rocks = new THREE.InstancedMesh(new THREE.DodecahedronGeometry(.5, 0), new THREE.MeshStandardMaterial({ color: 0x736b5b, roughness: 1, flatShading: true }), 30);
  for (let i = 0; i < 30; i++) {
    const x = -420 + rand() * 840, z = 112 + rand() * 30;
    setInstance(rocks, i, { x, y: .22, z }, { x: .5 + rand() * 1.8, y: .2 + rand() * .7, z: .5 + rand() * 1.6 }, { x: rand(), y: rand() * 6, z: rand() }, new THREE.Color(0x6d6759));
  }
  rocks.castShadow = true;
  scene.add(rocks);

  // ---------------- UPDATE ----------------
  world.getGroundHeight = (x, z) => {
    if (world.pierBounds && x > world.pierBounds.minX && x < world.pierBounds.maxX && z > world.pierBounds.minZ && z < world.pierBounds.maxZ) return .7;
    return 0;
  };

  world.districtAt = (x, z) => {
    for (const d of WORLD.districts) if (d.test(x, z)) return d;
    return WORLD.districts[0];
  };

  world.update = (dt, elapsed, playerPos, camera) => {
    world.time += dt;
    oceanUniforms.uTime.value = elapsed;
    skyUniforms.uTime.value = elapsed;
    stars.material.opacity = .2 + Math.sin(elapsed * .03) * .08;
    for (const fn of world.animate) fn(dt, elapsed);
    // keep the sun shadow frustum around the player
    if (playerPos) {
      sunLight.position.set(playerPos.x + sunDir.x * 170, sunDir.y * 170, playerPos.z + sunDir.z * 170);
      sunLight.target.position.set(playerPos.x, 0, playerPos.z);
      sunLight.target.updateMatrixWorld();
      sky.position.set(camera.position.x, 0, camera.position.z);
      sunSprite.position.set(camera.position.x + sunDir.x * 700, sunDir.y * 700, camera.position.z + sunDir.z * 700);
    }
    world.gulls = gulls;
  };

  world.setQuality = (preset) => {
    world.quality = preset;
    const high = preset !== 'performance';
    sunLight.castShadow = high;
    sunLight.shadow.mapSize.set(preset === 'ultra' ? 2048 : 1024, preset === 'ultra' ? 2048 : 1024);
    scene.fog.density = preset === 'performance' ? .0025 : .00135;
    if (preset === 'performance') {
      ocean.geometry.setDrawRange(0, Math.floor(ocean.geometry.attributes.position.count * .55) * 6);
    } else {
      ocean.geometry.setDrawRange(0, Infinity);
    }
  };

  return world;
}

import * as THREE from 'three';
import { addShadowBlob, clamp, damp, angleLerp } from './utils.js';

const SKIN = [0x8d583d, 0x6f412e, 0xb87b58, 0x5b3526, 0xd29b76, 0x9b6146, 0x4a2a20];
const SHIRTS = [0xf2e8d6, 0xd95a4b, 0x2e8c83, 0xf0ba4f, 0x314c72, 0x7b4b84, 0xc9c1af, 0x3b3b3f, 0xea8a5f];
const PANTS = [0x27343d, 0x3d3b48, 0xd6cbb5, 0x1f3a4a, 0x5b4a3c, 0x2e4e53, 0x38312f];

function mat(color, roughness = .85, metalness = 0) {
  return new THREE.MeshStandardMaterial({ color, roughness, metalness });
}

function makeLimb(w, h, d, m, pos) {
  const mesh = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), m);
  mesh.position.set(pos.x, pos.y, pos.z);
  mesh.castShadow = true;
  return mesh;
}

function createPistol() {
  const g = new THREE.Group();
  const metal = mat(0x252d31, .3, .8);
  const grip = mat(0x242021, .85, .1);
  const slide = new THREE.Mesh(new THREE.BoxGeometry(.09, .13, .42), metal);
  slide.position.set(0, .04, -.16); g.add(slide);
  const barrel = new THREE.Mesh(new THREE.CylinderGeometry(.02, .02, .18, 6), metal);
  barrel.rotation.x = Math.PI / 2; barrel.position.set(0, .04, -.47); g.add(barrel);
  const handle = new THREE.Mesh(new THREE.BoxGeometry(.1, .25, .13), grip);
  handle.position.set(0, -.12, .0); handle.rotation.x = -.22; g.add(handle);
  const guard = new THREE.Mesh(new THREE.TorusGeometry(.07, .012, 4, 8, Math.PI), metal);
  guard.rotation.y = Math.PI / 2; guard.rotation.z = Math.PI; guard.position.set(0, -.06, -.1); g.add(guard);
  g.userData.muzzle = new THREE.Object3D(); g.userData.muzzle.position.set(0, .04, -.56); g.add(g.userData.muzzle);
  g.visible = false;
  return g;
}

function createSMG() {
  const g = new THREE.Group();
  const metal = mat(0x272d2d, .35, .75);
  const body = new THREE.Mesh(new THREE.BoxGeometry(.13, .18, .6), metal); body.position.set(0, .04, -.2); g.add(body);
  const barrel = new THREE.Mesh(new THREE.CylinderGeometry(.035, .035, .34, 7), metal); barrel.rotation.x = Math.PI / 2; barrel.position.set(0, .04, -.62); g.add(barrel);
  const mag = new THREE.Mesh(new THREE.BoxGeometry(.08, .32, .11), mat(0x202b27, .8)); mag.position.set(0, -.18, -.15); mag.rotation.x = .15; g.add(mag);
  const stock = new THREE.Mesh(new THREE.BoxGeometry(.09, .12, .28), mat(0x302b28, .9)); stock.position.set(0, .01, .23); g.add(stock);
  g.userData.muzzle = new THREE.Object3D(); g.userData.muzzle.position.set(0, .04, -.8); g.add(g.userData.muzzle);
  g.visible = false;
  return g;
}

export function createCharacter(options = {}) {
  const female = options.female ?? false;
  const skin = options.skin ?? (female ? 0x8d583d : 0x6f412e);
  const shirt = options.shirt ?? (female ? 0xe4a33c : 0x2c8f85);
  const pants = options.pants ?? (female ? 0x384a61 : 0x343e45);
  const hair = options.hair ?? 0x211914;
  const accent = options.accent ?? 0xff7058;
  const isPlayer = options.isPlayer ?? false;
  const name = options.name ?? 'Cidadão';

  const root = new THREE.Group();
  root.name = 'character-' + name;
  const visual = new THREE.Group();
  root.add(visual);

  const skinM = mat(skin, .88);
  const shirtM = mat(shirt, .8);
  const pantsM = mat(pants, .9);
  const shoeM = mat(options.shoes ?? 0x1d1a19, .7);
  const hairM = mat(hair, .95);
  const eyeM = new THREE.MeshBasicMaterial({ color: 0x12100e });
  const lipM = mat(0x7a3b34, .9);

  // torso
  const torso = new THREE.Group();
  torso.position.y = .95;
  visual.add(torso);
  const chest = makeLimb(female ? .43 : .49, .58, .26, shirtM, { x: 0, y: .21, z: 0 });
  chest.geometry = new THREE.CylinderGeometry(female ? .23 : .255, female ? .2 : .22, .58, 7);
  chest.geometry.scale(1, 1, .7);
  chest.position.y = .2;
  torso.add(chest);
  if (female) {
    const waist = new THREE.Mesh(new THREE.CylinderGeometry(.18, .19, .24, 7), skinM);
    waist.scale.z = .68; waist.position.y = -.18; waist.castShadow = true; torso.add(waist);
  }
  const neck = new THREE.Mesh(new THREE.CylinderGeometry(.07, .09, .15, 7), skinM);
  neck.position.y = .57; neck.castShadow = true; torso.add(neck);

  // head
  const head = new THREE.Group();
  head.position.y = .76;
  torso.add(head);
  const skull = new THREE.Mesh(new THREE.SphereGeometry(.155, 12, 10), skinM);
  skull.scale.set(.9, 1.08, .92); skull.castShadow = true; head.add(skull);
  const jaw = new THREE.Mesh(new THREE.SphereGeometry(.12, 10, 8), skinM);
  jaw.scale.set(.95, .8, .9); jaw.position.set(0, -.09, .02); head.add(jaw);
  const nose = new THREE.Mesh(new THREE.ConeGeometry(.026, .07, 5), skinM);
  nose.rotation.x = Math.PI / 2; nose.position.set(0, -.015, .15); head.add(nose);
  for (const sx of [-1, 1]) {
    const eye = new THREE.Mesh(new THREE.SphereGeometry(.019, 6, 5), eyeM);
    eye.position.set(sx * .055, .03, .135); head.add(eye);
    const brow = new THREE.Mesh(new THREE.BoxGeometry(.055, .01, .012), hairM);
    brow.position.set(sx * .055, .075, .138); brow.rotation.z = sx * -.1; head.add(brow);
  }
  const lips = new THREE.Mesh(new THREE.BoxGeometry(female ? .068 : .06, .018, .012), lipM);
  lips.position.set(0, -.075, .14); head.add(lips);

  if (options.curly) {
    for (let i = 0; i < 12; i++) {
      const a = (i / 12) * Math.PI * 2;
      const curl = new THREE.Mesh(new THREE.SphereGeometry(.07 + (i % 3) * .012, 7, 6), hairM);
      curl.position.set(Math.cos(a) * .13, .09 + Math.sin(a * 2) * .05 + (i > 7 ? .02 : 0), Math.sin(a) * .11 - .03);
      curl.scale.set(1, 1.2, 1); curl.castShadow = true; head.add(curl);
    }
    const backHair = new THREE.Mesh(new THREE.SphereGeometry(.16, 10, 8), hairM);
    backHair.scale.set(1, 1.35, .8); backHair.position.set(0, .02, -.06); head.add(backHair);
  } else {
    const capMat = mat(options.capColor ?? accent, .8);
    const cap = new THREE.Mesh(new THREE.SphereGeometry(.166, 12, 8, 0, Math.PI * 2, 0, Math.PI / 2), capMat);
    cap.scale.set(1, .85, 1); cap.position.y = .055; cap.castShadow = true; head.add(cap);
    const brim = new THREE.Mesh(new THREE.BoxGeometry(.28, .022, .17), capMat);
    brim.position.set(0, .07, .14); brim.rotation.x = .07; head.add(brim);
    const hairFront = new THREE.Mesh(new THREE.BoxGeometry(.25, .03, .04), hairM);
    hairFront.position.set(0, .035, .125); head.add(hairFront);
  }

  // arms
  const arms = [];
  for (const sx of [-1, 1]) {
    const shoulder = new THREE.Group();
    shoulder.position.set(sx * (female ? .25 : .29), .38, 0);
    torso.add(shoulder);
    const upper = makeLimb(female ? .11 : .125, .3, .13, shirtM, { x: 0, y: -.14, z: 0 });
    shoulder.add(upper);
    const elbow = new THREE.Group();
    elbow.position.y = -.29;
    shoulder.add(elbow);
    const lower = makeLimb(female ? .09 : .1, .28, .11, skinM, { x: 0, y: -.13, z: 0 });
    elbow.add(lower);
    const hand = new THREE.Mesh(new THREE.BoxGeometry(.085, .11, .12), skinM);
    hand.position.set(0, -.3, .01); hand.castShadow = true; elbow.add(hand);
    if (options.chain && sx === 1) {
      const chain = new THREE.Mesh(new THREE.TorusGeometry(.07, .007, 4, 10), mat(0xf1c253, .3, .8));
      chain.rotation.x = Math.PI / 2; chain.position.set(0, .02, 0); shoulder.add(chain);
    }
    arms.push({ shoulder, elbow, hand });
  }
  // right arm is index 1, weapon attached
  const weapon = createPistol();
  weapon.position.set(0, -.32, -.02);
  weapon.rotation.x = -Math.PI / 2;
  arms[1].elbow.add(weapon);
  const smg = createSMG();
  smg.position.set(0, -.32, -.02);
  smg.rotation.x = -Math.PI / 2;
  arms[1].elbow.add(smg);

  // legs
  const legs = [];
  for (const sx of [-1, 1]) {
    const hip = new THREE.Group();
    hip.position.set(sx * .11, .92, 0);
    visual.add(hip);
    const upper = makeLimb(female ? .14 : .17, .42, .16, pantsM, { x: 0, y: -.2, z: 0 });
    hip.add(upper);
    const knee = new THREE.Group();
    knee.position.y = -.4;
    hip.add(knee);
    const lower = makeLimb(female ? .115 : .14, .39, .14, pantsM, { x: 0, y: -.18, z: 0 });
    knee.add(lower);
    const shoe = makeLimb(female ? .12 : .145, .1, .25, shoeM, { x: 0, y: -.39, z: .05 });
    knee.add(shoe);
    legs.push({ hip, knee, shoe });
  }

  // accessories
  if (options.earrings) {
    for (const sx of [-1, 1]) {
      const e = new THREE.Mesh(new THREE.TorusGeometry(.028, .006, 4, 8), mat(0xf3c24c, .3, .9));
      e.position.set(sx * .145, -.01, .01); e.rotation.y = Math.PI / 2; head.add(e);
    }
  }
  if (options.backpack) {
    const bag = new THREE.Mesh(new THREE.BoxGeometry(.32, .36, .16), mat(0x3c3530, .95));
    bag.position.set(0, .22, -.2); bag.castShadow = true; torso.add(bag);
    const strap = new THREE.Mesh(new THREE.BoxGeometry(.05, .5, .03), mat(0x272321, .95));
    strap.position.set(-.13, .3, .15); strap.rotation.z = .2; torso.add(strap);
  }

  const shadow = addShadowBlob(root, isPlayer ? 1.5 : 1.15);
  shadow.position.y = .015;

  const state = {
    root, visual, torso, head, arms, legs, weapon, smg, shadow,
    time: Math.random() * 10,
    aiming: false,
    speed: 0,
    phase: 0,
    currentWeapon: 'pistol',
    isPlayer,
    name
  };

  state.setWeapon = (kind) => {
    state.currentWeapon = kind;
    weapon.visible = kind === 'pistol' && (state.aiming || state.speed < .002);
    smg.visible = kind === 'smg' && (state.aiming || state.speed < .002);
  };

  state.setAiming = (aiming) => {
    state.aiming = aiming;
    state.setWeapon(state.currentWeapon);
  };

  state.update = (dt, opts = {}) => {
    state.time += dt;
    const speed = opts.speed ?? state.speed;
    const moving = speed > .08;
    const running = speed > 4.2;
    state.speed = speed;
    if (opts.aiming !== undefined) state.aiming = opts.aiming;
    state.setWeapon(state.currentWeapon);
    const period = running ? 7.8 : 5.4;
    if (moving) state.phase += dt * period * clamp(speed / 2.5, .6, 1.6);
    const swing = Math.sin(state.phase);
    const swing2 = Math.cos(state.phase);
    const amt = moving ? clamp(speed / 6.5, .2, 1) : 0;
    legs[0].hip.rotation.x = swing * .62 * amt;
    legs[1].hip.rotation.x = -swing * .62 * amt;
    legs[0].knee.rotation.x = Math.max(0, -swing) * .73 * amt;
    legs[1].knee.rotation.x = Math.max(0, swing) * .73 * amt;
    torso.position.y = .95 + Math.abs(swing2) * .025 * amt;
    torso.rotation.z = Math.sin(state.phase * .5) * .025 * amt;
    visual.rotation.z = Math.sin(state.phase) * .012 * amt;
    if (state.aiming) {
      arms[1].shoulder.rotation.x = -1.27;
      arms[1].shoulder.rotation.z = -.12;
      arms[1].elbow.rotation.x = -.1;
      arms[0].shoulder.rotation.x = -.9;
      arms[0].shoulder.rotation.z = .38;
      arms[0].elbow.rotation.x = -.65;
    } else {
      arms[0].shoulder.rotation.x = -swing * .55 * amt + Math.sin(state.time * 1.4) * .02;
      arms[1].shoulder.rotation.x = swing * .55 * amt + Math.sin(state.time * 1.35 + 1) * .02;
      arms[0].shoulder.rotation.z = .06;
      arms[1].shoulder.rotation.z = -.06;
      arms[0].elbow.rotation.x = -.1 - Math.max(0, -swing) * .2 * amt;
      arms[1].elbow.rotation.x = -.1 - Math.max(0, swing) * .2 * amt;
    }
    head.rotation.y = damp(head.rotation.y, opts.lookYaw || 0, 5, dt);
    head.rotation.x = damp(head.rotation.x, (opts.lookPitch || 0) * .4, 5, dt);
    if (opts.rotationY !== undefined) visual.rotation.y = angleLerp(visual.rotation.y, opts.rotationY, clamp(dt * 10, 0, 1));
    const dead = opts.dead;
    if (dead) {
      visual.rotation.z = damp(visual.rotation.z, Math.PI / 2, 4, dt);
      visual.position.y = damp(visual.position.y, .12, 4, dt);
      state.shadow.material.opacity = .3;
    } else {
      visual.position.y = damp(visual.position.y, 0, 8, dt);
    }
  };

  state.setVisibility = (v) => { root.visible = v; };

  state.dispose = () => {
    root.traverse(o => { if (o.isMesh) { o.geometry?.dispose?.(); if (Array.isArray(o.material)) o.material.forEach(m => m.dispose()); else o.material?.dispose?.(); } });
    root.parent?.remove(root);
  };

  return state;
}

