837:   drawMapCanvas(ctx, W, H, cx, cz, range, yaw, big) {
838:     const world = this.game.world;
839:     const game = this.game;
840:     const scale = Math.min(W, H) / range;
841:     const toX = (x) => W / 2 + (x - cx) * scale;
842:     const toY = (z) => H / 2 + (z - cz) * scale;
843:     ctx.clearRect(0, 0, W, H);
844:     ctx.fillStyle = big ? '#071c20' : '#09282d';
845:     ctx.fillRect(0, 0, W, H);
846:     // ocean
847:     ctx.fillStyle = big ? '#0d3d48' : '#0c353d';
848:     ctx.fillRect(0, 0, W, H);
849:     // city land
850:     ctx.fillStyle = big ? '#263b39' : '#203835';
851:     ctx.beginPath();
852:     ctx.rect(toX(-450), toY(-440), 900 * scale, 586 * scale);
853:     ctx.fill();
854:     // beach
855:     ctx.fillStyle = big ? '#c0a777' : '#a68f68';
856:     ctx.fillRect(toX(-450), toY(108), 900 * scale, 38 * scale);
857:     // promenade
858:     ctx.fillStyle = big ? '#6b7166' : '#596456';
859:     ctx.fillRect(toX(-450), toY(89), 900 * scale, 19 * scale);
860:     // blocks
861:     ctx.fillStyle = big ? '#334a47' : '#2b403d';
862:     for (const b of world.blocks) {
863:       const x = toX(b.minX), y = toY(b.minZ), w = (b.maxX - b.minX) * scale, h = (b.maxZ - b.minZ) * scale;
864:       if (x + w < 0 || x > W || y + h < 0 || y > H) continue;
865:       ctx.fillRect(x, y, w, h);
866:     }
867:     // park
868:     ctx.fillStyle = '#3e6249';
869:     ctx.fillRect(toX(-233), toY(-16), 108 * scale, 92 * scale);
870:     // roads
871:     ctx.strokeStyle = big ? '#7a8279' : '#69746c';
872:     ctx.lineWidth = Math.max(big ? 7 : 3, 14 * scale * .52);
873:     for (const r of world.roads) {
874:       ctx.beginPath();
875:       if (r.type === 'v') { ctx.moveTo(toX(r.x), toY(-385)); ctx.lineTo(toX(r.x), toY(89)); }
876:       else { ctx.moveTo(toX(-385), toY(r.z)); ctx.lineTo(toX(385), toY(r.z)); }
877:       ctx.stroke();
878:     }
879:     // beach avenue accent
880:     ctx.strokeStyle = 'rgba(246,199,104,.45)';
881:     ctx.lineWidth = Math.max(1, 2 * scale);
882:     ctx.beginPath(); ctx.moveTo(toX(-420), toY(82)); ctx.lineTo(toX(420), toY(82)); ctx.stroke();
883:     // coastline outline
884:     ctx.strokeStyle = 'rgba(177,238,226,.33)';
885:     ctx.lineWidth = 2;
886:     ctx.beginPath(); ctx.moveTo(toX(-450), toY(146)); ctx.lineTo(toX(450), toY(146)); ctx.stroke();
887:     // water waves
888:     ctx.strokeStyle = 'rgba(130,220,217,.06)';
889:     ctx.lineWidth = 1;
890:     for (let z = 180; z < 400; z += 24) { ctx.beginPath(); ctx.moveTo(toX(-450), toY(z)); ctx.lineTo(toX(450), toY(z)); ctx.stroke(); }
891:     // landmarks
892:     const locs = [
893:       { x: -352, z: 50, icon: '◉', color: '#f6c768', label: 'FAROL' },
894:       { x: 350, z: 30, icon: '⊙', color: '#ff7058', label: 'RODA' },
895:       { x: 17, z: -244, icon: '▲', color: '#43ddbe', label: 'TORRE' },
896:       { x: 108, z: 200, icon: '═', color: '#e6ddc8', label: 'PIER' },
897:       { x: -178, z: 30, icon: '✦', color: '#89c67a', label: 'PARK' }
898:     ];
899:     for (const l of locs) {
900:       const x = toX(l.x), y = toY(l.z);
901:       if (x < 0 || x > W || y < 0 || y > H) continue;
902:       ctx.fillStyle = l.color;
903:       ctx.beginPath(); ctx.arc(x, y, big ? 8 : 3, 0, Math.PI * 2); ctx.fill();
904:       if (big) { ctx.font = '600 15px Outfit'; ctx.fillStyle = 'rgba(248,246,236,.8)'; ctx.fillText(l.label, x + 14, y + 5); }
905:     }
906:     // district labels big
907:     if (big) {
908:       ctx.font = '700 20px "Barlow Condensed"'; ctx.fillStyle = 'rgba(238,244,238,.32)'; ctx.textAlign = 'center';
909:       const labels = [[-190, 55, 'ORLA CENTRAL'], [0, -60, 'CENTRO MARÉ'], [280, -90, 'PORTO MARÉ'], [-285, -210, 'MORRO DO SOM'], [295, 36, 'MARINA AZUL'], [-240, 10, 'JARDINS']];
910:       labels.forEach(([x, z, text]) => ctx.fillText(text, toX(x), toY(z)));
911:       ctx.textAlign = 'left';
912:     }
913:     // mission marker
914:     const marker = game.missionManager?.markerPos;
915:     if (marker) {
916:       const x = toX(marker.x), y = toY(marker.z);
917:       const pulse = 1 + Math.sin(performance.now() * .005) * .24;
918:       ctx.save();
919:       ctx.translate(x, y); ctx.rotate(Math.PI / 4);
920:       ctx.strokeStyle = '#f6c768'; ctx.lineWidth = big ? 4 : 2;
921:       ctx.strokeRect(-7 * pulse, -7 * pulse, 14 * pulse, 14 * pulse);
922:       ctx.fillStyle = 'rgba(246,199,104,.35)'; ctx.fillRect(-5, -5, 10, 10);
923:       ctx.restore();
924:     }
925:     // service markers if big
926:     if (big) {
927:       const services = [[-62, 95, '#ff7058'], [48, 95, '#43ddbe'], [168, 95, '#f6c768'], [126, -6, '#71c7ff']];
928:       services.forEach(([x, z, c]) => { ctx.fillStyle = c; ctx.beginPath(); ctx.arc(toX(x), toY(z), 4, 0, 7); ctx.fill(); });
929:     }
930:     // NPCs / hostiles / police
931:     for (const npc of game.npcs || []) {
932:       if (npc.dead) continue;
933:       const x = toX(npc.position.x), y = toY(npc.position.z);
934:       if (x < 0 || x > W || y < 0 || y > H) continue;
935:       ctx.fillStyle = 'rgba(220,235,228,.48)';
936:       ctx.fillRect(x - 1, y - 1, 2, 2);
937:     }
938:     for (const h of game.hostiles || []) {
939:       if (!h.alive) continue;
940:       const x = toX(h.position.x), y = toY(h.position.z);
941:       if (x < 0 || x > W || y < 0 || y > H) continue;
942:       ctx.fillStyle = h.kind === 'police' ? '#5b8cff' : '#ff554d';
943:       ctx.beginPath(); ctx.arc(x, y, big ? 4 : 2.4, 0, 7); ctx.fill();
944:     }
945:     for (const c of game.policeCars || []) {
946:       const x = toX(c.root.position.x), y = toY(c.root.position.z);
947:       if (x < 0 || x > W || y < 0 || y > H) continue;
948:       ctx.fillStyle = '#77a2ff'; ctx.fillRect(x - 2.5, y - 2.5, 5, 5);
949:     }
950:     // cars
951:     for (const v of game.vehicles || []) {
952:       if (v === game.activeVehicle || v.police) continue;
953:       const x = toX(v.root.position.x), y = toY(v.root.position.z);
954:       if (x < 0 || x > W || y < 0 || y > H) continue;
955:       ctx.fillStyle = 'rgba(235,232,220,.42)';
956:       ctx.fillRect(x - 1.5, y - 1.5, 3, 3);
957:     }
958:     // player arrow
959:     const px = toX(game.player.position.x), py = toY(game.player.position.z);
960:     ctx.save();
961:     ctx.translate(px, py);
962:     ctx.rotate(-yaw);
963:     ctx.fillStyle = '#fff9e8';
964:     ctx.strokeStyle = 'rgba(0,0,0,.5)'; ctx.lineWidth = 2;
965:     ctx.beginPath(); ctx.moveTo(0, -(big ? 13 : 10)); ctx.lineTo(big ? 8 : 6, big ? 9 : 7); ctx.lineTo(0, big ? 4 : 3.5); ctx.lineTo(big ? -8 : -6, big ? 9 : 7); ctx.closePath();
966:     ctx.fill(); ctx.stroke();
967:     ctx.restore();
968:     if (big) {
969:       ctx.strokeStyle = 'rgba(255,255,255,.08)'; ctx.lineWidth = 1;
970:       for (let x = -400; x <= 400; x += 100) { ctx.beginPath(); ctx.moveTo(toX(x), 0); ctx.lineTo(toX(x), H); ctx.stroke(); }
971:     }
972:     // vignette minimap
973:     if (!big) {
974:       const grad = ctx.createRadialGradient(W / 2, H / 2, W * .33, W / 2, H / 2, W * .5);
975:       grad.addColorStop(0, 'rgba(0,0,0,0)'); grad.addColorStop(1, 'rgba(0,0,0,.38)');
976:       ctx.fillStyle = grad; ctx.fillRect(0, 0, W, H);
977:     }
978:   }
