    } catch { /* pointer lock can be denied */ }
  }

  releaseInput() {
    this.keys.clear();
    this.mouseDown = false;
    this.aiming = false;
    try { if (document.pointerLockElement) document.exitPointerLock(); } catch { /* noop */ }
