    if (playing) {
      this.updateGameplay(dt);
      this.updateCamera(dt, false);
      this.hudTimer += dt;
      if (this.hudTimer > .1) {
        this.hudTimer = 0;
        this.refreshHUD();
      }
    } else if (this.state === 'dead') {
      this.updateCamera(dt, false);
    } else if (this.state === 'menu') {
