      lookY = 1.45;
    }
    const horiz = Math.cos(this.camPitch) * dist;
    this._desired.set(
      p.x + Math.sin(this.camYaw) * horiz,
      p.y + height,
      p.z + Math.cos(this.camYaw) * horiz
