      : (h < 6 ? 'LATE NIGHT' : h < 12 ? 'MORNING' : h < 18 ? 'AFTERNOON' : 'NIGHT');
    return `${days[new Date().getDay()]} · ${period}`;
  }

  addMoney(amount) {
    this.money = Math.max(0, this.money + amount);
    this.rp.money = this.money;
    this.moneyDelta = Math.max(0, amount);
