+    el.classList.remove('show');
+    void el.offsetWidth;
+    el.style.color = kill ? '#fff' : '#ffb49f';
+    el.classList.add('show');
+    setTimeout(() => el.classList.remove('show'), 260);
+    if (this.settings.haptics && navigator.vibrate) navigator.vibrate(kill ? 18 : 8);
+  }
+
+  killHostile(h) {
+    if (!h.alive) return;
