+        hospital: [['Hospital da Maré', 'Maré Hospital']], delivery: [['Morro do Som', 'Sound Hill']], park: [['Parque das Salinas', 'Salt Park']],
+        lighthouse: [['Farol Velho', 'Old Lighthouse']]
